export const REPO='CameronNel/Cam-s-Health';
export const DATA_PATH='dist/data/health.json';
export const round=n=>Math.round((Number(n)||0)*10)/10;
export function today(timezone='Europe/Amsterdam',now=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(now);}
export function totals(day){return (day?.food||[]).reduce((t,f)=>{for(const k of ['kcal','protein','carbs','fat']){t[k]=round(t[k]+(f[k]??0));if(f[k]==null)t.missing[k]++;}t.estimated+=f.estimated?1:0;t.pending+=['kcal','protein','carbs','fat'].some(k=>f[k]==null)?1:0;return t;},{kcal:0,protein:0,carbs:0,fat:0,estimated:0,pending:0,missing:{kcal:0,protein:0,carbs:0,fat:0}});}
export function shiftDate(date,n){const d=new Date(date+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);}
export function dayFor(data,date){return data.days[date]||{food:[],workouts:[],steps:null,waterMl:null,weightKg:null,notes:''};}
export function nextSession(data,date){const completed=Object.entries(data.days).filter(([d])=>d<=date).sort(([a],[b])=>a.localeCompare(b)).flatMap(([,d])=>(d.workouts||[]).filter(w=>w.status==='completed'&&w.sessionId));const ids=data.training.rotation;const last=completed.at(-1);let i=last?ids.indexOf(last.sessionId)+1:0;if(i>=ids.length)i=0;return data.training.sessions.find(s=>s.id===ids[i])||null;}
export function validate(data){if(data?.schemaVersion!==1||!data.profile||!data.days||!Array.isArray(data.training?.rotation)||!data.training.rotation.length||!Array.isArray(data.training.sessions))throw Error('Unsupported or incomplete health file.');const finite=(n,label,max=100000)=>{if(n!==null&&(!Number.isFinite(n)||n<0||n>max))throw Error(`Invalid ${label}.`);};for(const k of ['kcal','protein','carbs','fat','steps'])finite(data.profile.targets[k]??null,k);const ids=new Set();for(const s of data.training.sessions){if(!s.id||ids.has(s.id)||!Array.isArray(s.exercises))throw Error('Invalid training sessions.');ids.add(s.id);}for(const id of data.training.rotation)if(!ids.has(id))throw Error('Unknown session in rotation.');for(const [date,day]of Object.entries(data.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||shiftDate(date,0)!==date)throw Error('Invalid date.');if(!Array.isArray(day.food)||!Array.isArray(day.workouts))throw Error('Missing day entries.');const entries=new Set();for(const f of day.food){if(!f.id||entries.has(f.id)||!f.name)throw Error('Invalid or duplicate food entry.');entries.add(f.id);for(const k of ['kcal','protein','carbs','fat'])finite(f[k],k);}for(const w of day.workouts){if(!w.id||entries.has(w.id))throw Error('Invalid or duplicate workout.');entries.add(w.id);finite(w.durationMin??null,'duration',1440);if(w.sessionId&&!ids.has(w.sessionId))throw Error('Unknown workout session.');}finite(day.steps??null,'steps',200000);finite(day.waterMl??null,'water',20000);finite(day.weightKg??null,'weight',500);}return data;}
export function brief(data,date){const day=dayFor(data,date),t=totals(day),p=data.profile.targets;if(!day.food.length)return `${date} · Food not logged.\nSteps: ${day.steps==null?'not logged':day.steps.toLocaleString()} / ${p.steps??'—'}\nTraining: ${day.workouts.length?day.workouts.map(w=>w.name+' ('+w.status+')').join(', '):'not logged'}\nNext session: ${nextSession(data,date)?.name||'not set'}.`;return `${date}${t.pending?' · Known subtotals (incomplete)':''} · ${t.kcal} / ${p.kcal??'—'} kcal · Protein ${t.protein} / ${p.protein??'—'} g · Carbs ${t.carbs} g · Fat ${t.fat} g\nSteps: ${day.steps==null?'not logged':day.steps.toLocaleString()} / ${p.steps??'—'}\nTraining: ${day.workouts.length?day.workouts.map(w=>`${w.name} (${w.status}${w.durationMin!=null?', '+w.durationMin+' min':''})`).join(', '):'not logged'}\n${t.estimated?'Food totals include estimates. ':''}${t.pending?t.pending+' food entries are incomplete. ':''}Next session: ${nextSession(data,date)?.name||'not set'}.`;}
